// Package apidocs embeds the generated API documentation.
//
// swagger.json (Swagger 2.0) is generated by swag from the annotations on
// cmd/bmcproxy (general info), internal/... handlers, pkg/bmc types and
// vendors/... route handlers; openapi.json (OpenAPI 3) is converted and
// validated from it by cmd/openapigen. Both are committed and regenerated
// with `go generate ./internal/apidocs` (or `make generate`); `make
// check-openapi` fails when the committed files are stale.
package apidocs

import _ "embed"

//go:generate go run github.com/swaggo/swag/cmd/swag init --quiet -g main.go -d ../../cmd/bmcproxy,../../internal,../../pkg/bmc,../../vendors -o . --outputTypes json --parseInternal --parseDependency --parseDepth 2 --overridesFile .swaggo
//go:generate go run ../../cmd/openapigen -in swagger.json -out openapi.json

// OpenAPI is the OpenAPI 3 document (served at /openapi.json).
//
//go:embed openapi.json
var OpenAPI []byte

// Swagger is the Swagger 2.0 document as generated by swag (served at
// /swagger/doc.json).
//
//go:embed swagger.json
var Swagger []byte
